class SinkronWorker(ctx: Context, params: WorkerParameters, private val repo: CatatanRepo) : CoroutineWorker(ctx, params) {
    override suspend fun doWork(): Result = try {
        repo.sinkron()
        Result.success()
    } catch (e: IOException) {
        if (runAttemptCount < 5) Result.retry() else Result.failure()
    }
}

val kerja = PeriodicWorkRequestBuilder<SinkronWorker>(6, TimeUnit.HOURS)
    .setConstraints(Constraints(requiredNetworkType = NetworkType.CONNECTED, requiresBatteryNotLow = true))
    .setBackoffCriteria(BackoffPolicy.EXPONENTIAL, 30, TimeUnit.SECONDS)
    .build()
WorkManager.getInstance(ctx).enqueueUniquePeriodicWork("sinkron", ExistingPeriodicWorkPolicy.KEEP, kerja)

