@Module @InstallIn(SingletonComponent::class)
abstract class RepoModule { @Binds abstract fun produkRepo(impl: ProdukRepositoryImpl): ProdukRepository }

interface TokoApi {
    @GET("produk") suspend fun produk(@Query("halaman") halaman: Int = 1): List<ProdukDto>
}

class ProdukRepositoryImpl @Inject constructor(private val api: TokoApi, private val dao: ProdukDao) : ProdukRepository {
    override fun pantau(): Flow<List<Produk>> = dao.semua().map { it.map(ProdukEntity::keDomain) }

    override suspend fun segarkan(): Result<Unit> = runCatching {
        val dto = api.produk()
        dao.gantiSemua(dto.map(ProdukDto::keEntity)) // UI otomatis ikut berubah lewat Flow
    }
}

class ProdukPagingSource(private val api: TokoApi) : PagingSource<Int, ProdukDto>() {
    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, ProdukDto> = try {
        val hal = params.key ?: 1
        val data = api.produk(halaman = hal)
        LoadResult.Page(data, prevKey = if (hal == 1) null else hal - 1, nextKey = if (data.isEmpty()) null else hal + 1)
    } catch (e: IOException) {
        LoadResult.Error(e)
    }
    override fun getRefreshKey(state: PagingState<Int, ProdukDto>) = state.anchorPosition?.let { state.closestPageToPosition(it)?.prevKey?.plus(1) }
}

