Iterable<int> fibonacci() sync* {
  var a = 0, b = 1;
  while (true) {
    yield a;
    (a, b) = (b, a + b);
  }
}

void main() {
  print(fibonacci().take(10).toList());
  print(fibonacci().firstWhere((x) => x > 1000));
}

int hitungOngkir({required int beratGram, String layanan = 'reguler', bool asuransi = false}) {
  final perKg = layanan == 'kilat' ? 18000 : 9000;
  final kg = (beratGram / 1000).ceil();
  return kg * perKg + (asuransi ? 2500 : 0);
}

void main() {
  print(hitungOngkir(beratGram: 1200));
  print(hitungOngkir(beratGram: 800, layanan: 'kilat', asuransi: true));
}

void main() {
  final kursi = [
    [1, 1, 1],
    [1, 0, 1],
    [0, 0, 1],
  ];
  String? hasil;
  luar:
  for (var b = 0; b < kursi.length; b++) {
    for (var k = 0; k < kursi[b].length; k++) {
      if (kursi[b][k] == 0) {
        hasil = 'baris ${b + 1}, kursi ${k + 1}';
        break luar;
      }
    }
  }
  print(hasil ?? 'penuh');
}

bool tombolBayarAktif({required bool login, required int item, required bool alamatLengkap, required bool sedangMemuat}) =>
    login && item > 0 && alamatLengkap && !sedangMemuat;

void main() {
  print(tombolBayarAktif(login: true, item: 2, alamatLengkap: true, sedangMemuat: false));
  print(tombolBayarAktif(login: true, item: 0, alamatLengkap: true, sedangMemuat: false));
  // De Morgan: alasan tombol mati
  final mati = !true || 2 <= 0 || !false || true;
  print(mati);
}

