import numpy as np
def gini(p): return 1 - np.sum(np.square(p))
def entropy(p): p = np.array([x for x in p if x > 0]); return -np.sum(p * np.log2(p))
for p in [(1, 0), (0.9, 0.1), (0.7, 0.3), (0.5, 0.5)]:
    print(f'proporsi {p}: Gini={gini(p):.3f}  entropy={entropy(p):.3f}')

import numpy as np
rng = np.random.default_rng(0)
topik = {'pembayaran': rng.normal(size=8), 'pengiriman': rng.normal(size=8), 'akun': rng.normal(size=8)}
dokumen = {'Cara bayar dengan QRIS': topik['pembayaran'] + rng.normal(0, .3, 8),
           'Lacak paket kurir': topik['pengiriman'] + rng.normal(0, .3, 8),
           'Lupa kata sandi': topik['akun'] + rng.normal(0, .3, 8)}
kueri = topik['pengiriman'] + rng.normal(0, .3, 8)          # "paket saya belum sampai"
skor = {d: v @ kueri / (np.linalg.norm(v) * np.linalg.norm(kueri)) for d, v in dokumen.items()}
for d, s in sorted(skor.items(), key=lambda x: -x[1]):
    print(f'{s:.2f}  {d}')

