class Keranjang extends ChangeNotifier {
  final Map<int, int> _qty = {};
  int get jumlahItem => _qty.values.fold(0, (a, b) => a + b);
  void tambah(int produkId) {
    _qty.update(produkId, (q) => q + 1, ifAbsent: () => 1);
    notifyListeners();
  }
}

