Future<void> ambilFotoKtp(BuildContext context) async {
  var status = await Permission.camera.status;
  if (status.isDenied) {
    final setuju = await tampilkanAlasan(context, 'Kamera dipakai untuk memotret KTP saat verifikasi akun.');
    if (!setuju) return;
    status = await Permission.camera.request();
  }
  if (status.isPermanentlyDenied) {
    await openAppSettings();
    return;
  }
  if (status.isGranted) {
    final foto = await ImagePicker().pickImage(source: ImageSource.camera, imageQuality: 70, maxWidth: 1600);
    if (foto != null) unggah(foto);
  }
}

abstract interface class ProdukRepository {
  Future<List<Produk>> daftar({bool paksaSegarkan = false});
}

class ProdukRepositoryImpl implements ProdukRepository {
  ProdukRepositoryImpl(this._api, this._db);
  final ProdukApi _api;
  final ProdukDao _db;

  @override
  Future<List<Produk>> daftar({bool paksaSegarkan = false}) async {
    if (!paksaSegarkan) {
      final lokal = await _db.semua();
      if (lokal.isNotEmpty) return lokal;
    }
    final segar = await _api.produk();
    await _db.simpanSemua(segar);
    return segar;
  }
}

