public class Main {
    static long hargaAkhir(long harga, int diskonPersen) {
        if (harga <= 0) return 0;
        if (diskonPersen > 50) diskonPersen = 50; // batas diskon kebijakan toko
        return harga - harga * diskonPersen / 100;
    }

    public static void main(String[] args) throws Exception {
        System.out.println(hargaAkhir(200_000, 10));
        System.out.println(hargaAkhir(200_000, 95));
        System.out.println(hargaAkhir(-5, 10));
    }
}

