import java.lang.annotation.*;
import java.lang.reflect.*;

public class Main {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD)
    @interface Wajib {}

    static class Daftar {
        @Wajib String nama; @Wajib String email;
        Daftar(String n, String e) { nama = n; email = e; }
    }

    static String validasi(Object o) {
        try {
            for (Field f : o.getClass().getDeclaredFields()) {
                if (f.isAnnotationPresent(Wajib.class) && ((String) f.get(o)).isBlank()) return f.getName() + " wajib diisi";
            }
            return "valid";
