public class Main {
    static class Node { int v; Node next; Node(int v, Node n) { this.v = v; next = n; } }
    static void cetak(Node h) {
        StringBuilder sb = new StringBuilder();
        for (Node n = h; n != null; n = n.next) sb.append(n.v).append(' ');
        System.out.println(sb.toString().trim());
    }

    public static void main(String[] args) throws Exception {
        Node h = null;
        for (int i = 5; i >= 1; i--) h = new Node(i, h);
        cetak(h);
        Node prev = null, cur = h;
        while (cur != null) { Node nx = cur.next; cur.next = prev; prev = cur; cur = nx; }
        cetak(prev);
    }
}

