         PreparedStatement pesan = c.prepareStatement(
             "INSERT INTO pesanan (pelanggan_id, total) VALUES (?, ?)")) {
        kurangi.setInt(1, qty); kurangi.setLong(2, produkId); kurangi.setInt(3, qty);
        if (kurangi.executeUpdate() == 0) throw new IllegalStateException("stok tidak cukup");
        pesan.setLong(1, pelangganId); pesan.setLong(2, total);
        pesan.executeUpdate();
        c.commit();
