EVENT = ["bayar", "batal", "kirim", "terima", "retur"]

def proses(status, event):            # sistem yang diuji
    if (status, event) not in TRANSISI:
        raise ValueError(f"transisi {status} --{event}--> tidak diizinkan")
    return TRANSISI[(status, event)]

