         ("Teks/Judul H1", "700 40/48 Fraunces"), ("Teks/Isi", "400 16/26 Inter")]
def slug(s):
    return s.lower().replace("warna/", "color-").replace("teks/", "type-").replace(" ", "-")
print(":root {")
for nama, v in style:
